var DICT={'光合作用':'光能转化为化学能，储存在有机物里','圆周率':'山巅一寺一壶酒(3.14159)谐音记小数','元素周期表':'从前(氢)住宿(锂)那(钠)里(钾)的(钙)美(镁)女(铝)…','RGB':'红绿蓝三原色，加色混合','CPU':'中央处理器，计算机的大脑','DNA':'双螺旋结构，承载遗传信息'};
function lookup(term){ if(!term) return null; return DICT[String(term).trim()]||null; }
function initialism(text){ return String(text).split(/\s+/).map(function(w){ w=w.replace(/[^A-Za-z]/g,''); return w.slice(0,1); }).filter(Boolean).join('').toUpperCase(); }
function soundAlike(word){ var m={'3.14':'山药(山巅一寺)','π':'派','CPU':'西皮优','URL':'哟儿'}; return m[String(word)]||null; }
var EXPORTS={DICT:DICT,lookup:lookup,initialism:initialism,soundAlike:soundAlike};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.MnemonicForgePure = EXPORTS; }
